#!/usr/bin/env bash
set -euo pipefail

echo 'Submitting strict-final missing jobs via direct proxy SSH'

echo 'submit strict_final_same_write_wait_complete_r2 invisible'
ssh -F /dev/null -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o 'ProxyCommand=ssh -F /dev/null -i '"'"'~/.ssh/id_rsa'"'"' -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o KexAlgorithms=+diffie-hellman-group-exchange-sha1,diffie-hellman-group14-sha1,diffie-hellman-group1-sha1 -o HostKeyAlgorithms=+ssh-rsa -W %h:%p zhanzhao@faith.comp.hkbu.edu.hk' 25482351@172.27.244.19 'cd ~/aegiskv_sglang_small && RUN_LABEL=strict_final_same_write_wait_complete_r2_host_invisible_lookup_disabled PORT=32828 REMOTE_BACKUP_PORT=33828 ENABLE_REMOTE_BACKUP=1 DISABLE_FAILOVER_REMOTE_LOOKUP=1 HICACHE_STORAGE_PREFETCH_POLICY=wait_complete REMOTE_BACKUP_REQUEST_AWARE=1 REMOTE_BACKUP_BUFFER_GB=16 NUM_REQUESTS=4 MAX_TOKENS=512 PROMPT_REPEAT=256 UNIQUE_REQUEST_PREFIX=0 FAILURE_DELAY_S=12 READY_TIMEOUT_S=2400 REQUEST_TIMEOUT_S=900 sbatch slurm/aegiskv_dp2_failure_smoke.sbatch'
echo 'submit strict_final_same_write_wait_complete_r2 visible'
ssh -F /dev/null -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o 'ProxyCommand=ssh -F /dev/null -i '"'"'~/.ssh/id_rsa'"'"' -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o KexAlgorithms=+diffie-hellman-group-exchange-sha1,diffie-hellman-group14-sha1,diffie-hellman-group1-sha1 -o HostKeyAlgorithms=+ssh-rsa -W %h:%p zhanzhao@faith.comp.hkbu.edu.hk' 25482351@172.27.244.19 'cd ~/aegiskv_sglang_small && RUN_LABEL=strict_final_same_write_wait_complete_r2_host_visible_lookup_enabled PORT=32829 REMOTE_BACKUP_PORT=33829 ENABLE_REMOTE_BACKUP=1 DISABLE_FAILOVER_REMOTE_LOOKUP=0 HICACHE_STORAGE_PREFETCH_POLICY=wait_complete REMOTE_BACKUP_REQUEST_AWARE=1 REMOTE_BACKUP_BUFFER_GB=16 NUM_REQUESTS=4 MAX_TOKENS=512 PROMPT_REPEAT=256 UNIQUE_REQUEST_PREFIX=0 FAILURE_DELAY_S=12 READY_TIMEOUT_S=2400 REQUEST_TIMEOUT_S=900 sbatch slurm/aegiskv_dp2_failure_smoke.sbatch'

echo 'submit strict_final_same_write_wait_complete_r3 invisible'
ssh -F /dev/null -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o 'ProxyCommand=ssh -F /dev/null -i '"'"'~/.ssh/id_rsa'"'"' -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o KexAlgorithms=+diffie-hellman-group-exchange-sha1,diffie-hellman-group14-sha1,diffie-hellman-group1-sha1 -o HostKeyAlgorithms=+ssh-rsa -W %h:%p zhanzhao@faith.comp.hkbu.edu.hk' 25482351@172.27.244.19 'cd ~/aegiskv_sglang_small && RUN_LABEL=strict_final_same_write_wait_complete_r3_host_invisible_lookup_disabled PORT=32830 REMOTE_BACKUP_PORT=33830 ENABLE_REMOTE_BACKUP=1 DISABLE_FAILOVER_REMOTE_LOOKUP=1 HICACHE_STORAGE_PREFETCH_POLICY=wait_complete REMOTE_BACKUP_REQUEST_AWARE=1 REMOTE_BACKUP_BUFFER_GB=16 NUM_REQUESTS=4 MAX_TOKENS=512 PROMPT_REPEAT=256 UNIQUE_REQUEST_PREFIX=0 FAILURE_DELAY_S=12 READY_TIMEOUT_S=2400 REQUEST_TIMEOUT_S=900 sbatch slurm/aegiskv_dp2_failure_smoke.sbatch'
echo 'submit strict_final_same_write_wait_complete_r3 visible'
ssh -F /dev/null -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o 'ProxyCommand=ssh -F /dev/null -i '"'"'~/.ssh/id_rsa'"'"' -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new -o KexAlgorithms=+diffie-hellman-group-exchange-sha1,diffie-hellman-group14-sha1,diffie-hellman-group1-sha1 -o HostKeyAlgorithms=+ssh-rsa -W %h:%p zhanzhao@faith.comp.hkbu.edu.hk' 25482351@172.27.244.19 'cd ~/aegiskv_sglang_small && RUN_LABEL=strict_final_same_write_wait_complete_r3_host_visible_lookup_enabled PORT=32831 REMOTE_BACKUP_PORT=33831 ENABLE_REMOTE_BACKUP=1 DISABLE_FAILOVER_REMOTE_LOOKUP=0 HICACHE_STORAGE_PREFETCH_POLICY=wait_complete REMOTE_BACKUP_REQUEST_AWARE=1 REMOTE_BACKUP_BUFFER_GB=16 NUM_REQUESTS=4 MAX_TOKENS=512 PROMPT_REPEAT=256 UNIQUE_REQUEST_PREFIX=0 FAILURE_DELAY_S=12 READY_TIMEOUT_S=2400 REQUEST_TIMEOUT_S=900 sbatch slurm/aegiskv_dp2_failure_smoke.sbatch'

